1	/**
2	 * Critical 临界值强制选择系统
3	 *
4	 * 核心循环：
5	 *   1. consumeAP / endDay 之前调用 checkCriticalNeeds(state)
6	 *   2. 任一状态 ≤ 阈值且当日未延期过 → 弹出强制选择窗
7	 *      - "立即去 XX": 自动旅行 + 消费 + 补充
8	 *      - "后续自己再去": 标记 _deferred[need]=day，关闭弹窗
9	 *   3. endDay 时 applyDeferredCriticalPunishments(state)
10	 *      - 已延期且仍 ≤ 阈值 → 按维度差异化掷骰惩罚
11	 *
12	 * 阈值（参考《大多数》生存张力）:
13	 *   hunger     ≤ 10   再不吃要饿晕
14	 *   fatigue    ≥ 90   累得快倒下
15	 *   hygiene    ≤ 10   脏到要生病
16	 *   happiness  ≤ 10   抑郁到崩溃
17	 */
18	
19	// ====== 阈值配置 ======
20	var CRITICAL_THRESHOLDS = {
21	  hunger: {
22	    type: "low",
23	    value: 10,
24	    amenityType: "food",
25	    label: "饥饱",
26	    icon: "🍚",
27	  },
28	  fatigue: {
29	    type: "high",
30	    value: 90,
31	    amenityType: "rest",
32	    label: "疲劳",
33	    icon: "😴",
34	  },
35	  hygiene: {
36	    type: "low",
37	    value: 10,
38	    amenityType: "bath",
39	    label: "卫生",
40	    icon: "🛁",
41	  },
42	  happiness: {
43	    type: "low",
44	    value: 10,
45	    amenityType: "fun",
46	    label: "心情",
47	    icon: "😊",
48	  },
49	};
50	
51	/** 判断某个状态是否处于临界值 */
52	function isCriticalNeed(state, key) {
53	  var cfg = CRITICAL_THRESHOLDS[key];
54	  if (!cfg) return false;
55	  var v = state.needs[key];
56	  if (v == null) return false;
57	  return cfg.type === "low" ? v <= cfg.value : v >= cfg.value;
58	}
59	
60	/** 找到当前需要紧急处理的临界状态（一次只弹一个，按优先级） */
61	function findCriticalNeed(state) {
62	  // 优先级：饥饱 > 疲劳 > 卫生 > 心情（饿晕最致命）
63	  var order = ["hunger", "fatigue", "hygiene", "happiness"];
64	  if (!state.flags._deferred) state.flags._deferred = {};
65	  for (var i = 0; i < order.length; i++) {
66	    var k = order[i];
67	    if (!isCriticalNeed(state, k)) continue;
68	    // 当日已延期则跳过（避免反复弹同一个）
69	    if (state.flags._deferred[k] === state.player.day) continue;
70	    return k;
71	  }
72	  return null;
73	}
74	
75	/**
76	 * 主入口 — 检查临界状态，需要时弹出强制选择窗。
77	 * 返回 true 表示弹出了窗（调用方应中断本次行动）。
78	 */
79	function checkCriticalNeeds(state) {
80	  // 弹窗模态时不嵌套触发
81	  if (document.querySelector(".modal-overlay")) return false;
82	  // 游戏未开始或已结束不触发
83	  if (!state || state.flags.gameOver || state.flags.victory) return false;
84	  // 极端临界（≤5）由 checkExtremeConditions 接管，避免冲突
85	  if (
86	    state.needs.hunger <= 5 ||
87	    state.needs.fatigue >= 98 ||
88	    state.status.health <= 5
89	  )
90	    return false;
91	
92	  var need = findCriticalNeed(state);
93	  if (!need) return false;
94	  showCriticalChoiceModal(state, need);
95	  return true;
96	}
97	
98	// ====== UI: 强制选择弹窗 ======
99	
100	function showCriticalChoiceModal(state, need) {
101	  var cfg = CRITICAL_THRESHOLDS[need];
102	  var curVal = state.needs[need];
103	
104	  // 找最近的 3 个对应类型 amenity
105	  var nearest =
106	    typeof getNearestAmenitiesByType === "function"
107	      ? getNearestAmenitiesByType(state, cfg.amenityType, 4)
108	      : [];
109	
110	  // 描述文案（按维度+严重度）
111	  var msg = _getCriticalMsg(need, curVal);
112	
113	  // 构造按钮
114	  var buttons = [];
115	  for (var i = 0; i < nearest.length; i++) {
116	    var n = nearest[i];
117	    var a = n.amenity;
118	    var travelAp = 0;
119	    if (n.actualLoc !== state.trade.currentLocation) {
120	      travelAp =
121	        typeof getTravelApCost === "function"
122	          ? getTravelApCost(state.trade.currentLocation, n.actualLoc, state)
123	          : 12;
124	    }
125	    var totalAp = travelAp + (a.ap || 0);
126	    var totalCost = a.cost || 0;
127	    var locName =
128	      LOCATIONS[n.actualLoc] && LOCATIONS[n.actualLoc].name
129	        ? LOCATIONS[n.actualLoc].name
130	        : n.actualLoc;
131	    var affordable = state.resources.cash >= totalCost;
132	    var hasAp = state.player.actionPoints >= totalAp;
133	
134	    var btnText =
135	      a.icon +
136	      " " +
137	      a.name +
138	      "（" +
139	      locName +
140	      "）¥" +
141	      totalCost +
142	      " · " +
143	      totalAp +
144	      "AP";
145	
146	    buttons.push({
147	      text: btnText,
148	      cls: affordable && hasAp ? "btn-primary" : "",
149	      _disabled: !affordable || !hasAp,
150	      callback: (function (amenityId) {
151	        return function () {
152	          travelToAmenityAndUse(amenityId);
153	        };
154	      })(a.id),
155	    });
156	  }
157	
158	  // 总有"后续自己再去"
159	  buttons.push({
160	    text: "🚶 后续自己再去",
161	    cls: "",
162	    callback: function () {
163	      var st = StateManager.getState();
164	      st.flags._deferred = st.flags._deferred || {};
165	      st.flags._deferred[need] = st.player.day;
166	      StateManager.addMessage(
167	        "⏳ 你决定" + cfg.label + "的事后续自己处理...小心后果。",
168	        "warning",
169	      );
170	    },
171	  });
172	
173	  // 渲染弹窗
174	  showModal({
175	    title: "⚠️ 该补充" + cfg.label + "了！",
176	    body:
177	      '<div style="font-size:13px;line-height:1.7;">' +
178	      msg +
179	      '<div style="margin-top:10px;padding:8px;background:var(--bg-input);border-radius:4px;">' +
180	      "当前 " +
181	      cfg.icon +
182	      " " +
183	      cfg.label +
184	      '：<strong style="color:var(--danger);">' +
185	      curVal +
186	      "</strong>" +
187	      "</div>" +
188	      (nearest.length === 0
189	        ? '<p style="margin-top:8px;color:var(--text-muted);">附近暂无可用的恢复点，只能暂时撑着...</p>'
190	        : '<p style="margin-top:8px;color:var(--text-muted);font-size:11px;">点击下方"立即去"自动前往并消费；选"后续自己再去"则今天结束时若状态仍未恢复，会有不可预料的后果。</p>') +
191	      "</div>",
192	    buttons: buttons,
193	  });
194	
195	  // 标记禁用按钮（modal.js 不支持 disabled，加个事后样式）
196	  setTimeout(function () {
197	    var btns = document.querySelectorAll(".modal-actions .btn");
198	    var idx = 0;
199	    for (var i = 0; i < buttons.length; i++) {
200	      var b = buttons[i];
201	      if (b._disabled && btns[idx]) {
202	        btns[idx].style.opacity = "0.4";
203	        btns[idx].title = "钱不够或行动力不足";
204	      }
205	      idx++;
206	    }
207	  }, 0);
208	}
209	
210	function _getCriticalMsg(need, val) {
211	  if (need === "hunger") {
212	    if (val <= 5) return "💀 饿到眼前发黑，再不吃就要昏倒了！";
213	    if (val <= 8) return "🍞 肚子咕咕叫，胃酸翻涌，必须吃点东西。";
214	    return "🍞 已经饿得不行了，赶紧找点吃的。";
215	  }
216	  if (need === "fatigue") {
217	    if (val >= 95) return "😵 眼皮在打架，随时可能晕倒在街上！";
218	    if (val >= 90) return "🥵 累得腿都抬不起来，再撑着会出事。";
219	    return "🥱 浑身酸痛、思维迟钝，必须休息了。";
220	  }
221	  if (need === "hygiene") {
222	    if (val <= 5) return "🦠 浑身发臭，皮肤瘙痒，路人都绕着走。";
223	    return "🦠 已经几天没洗澡了，再不洗要生病。";
224	  }
225	  if (need === "happiness") {
226	    if (val <= 5) return "🌧️ 心如死灰，做什么都没意思。需要去散散心。";
227	    return "😔 心情低落到谷底，再这样下去人会废掉。";
228	  }
229	  return "状态告急，需要补充。";
230	}
231	
232	// ====== Amenity 使用核心逻辑 ======
233	
234	/**
235	 * 自动旅行到指定 amenity 所在地并消费使用。
236	 * 含旅行AP+amenity AP+cash 校验。
237	 */
238	function travelToAmenityAndUse(amenityId) {
239	  var state = StateManager.getState();
240	  var a = getAmenityById(amenityId);
241	  if (!a) {
242	    StateManager.addMessage("❌ 找不到该恢复点。", "danger");
243	    return;
244	  }
245	
246	  var actualLoc = a.loc;
247	  if (a.loc === "*selfLive") {
248	    actualLoc = getSelfLiveLocKey(state);
249	    // 无自住房时尝试普通住所定位（租房也能做饭/洗澡）
250	    if (!actualLoc && typeof getHomeLocationKey === "function") {
251	      actualLoc = getHomeLocationKey(state);
252	    }
253	    if (!actualLoc) {
254	      StateManager.addMessage("❌ 你还没有住所。", "warning");
255	      return;
256	    }
257	  }
258	
259	  var curLoc = state.trade.currentLocation;
260	  var travelAp = 0;
261	  if (actualLoc !== curLoc) {
262	    travelAp = getTravelApCost(curLoc, actualLoc, state);
263	  }
264	  var useAp = a.ap || 0;
265	  var totalAp = travelAp + useAp;
266	  var cost = a.cost || 0;
267	
268	  if (state.resources.cash < cost) {
269	    StateManager.addMessage("💸 现金不足 ¥" + cost + "，无法消费。", "warning");
270	    return;
271	  }
272	  if (state.player.actionPoints < totalAp) {
273	    StateManager.addMessage(
274	      "⚡ 行动力不足（需要 " + totalAp + " AP）。",
275	      "warning",
276	    );
277	    return;
278	  }
279	
280	  // 食谱选择模式（在家做饭 → 弹出食谱选择界面）
281	  if (a.useRecipeSelection && typeof showCookingRecipeModal === "function") {
282	    showCookingRecipeModal(state, a, totalAp, cost);
283	    return;
284	  }
285	
286	  // 执行旅行
287	  if (actualLoc !== curLoc) {
288	    StateManager.update("trade.currentLocation", actualLoc);
289	    var locName =
290	      (LOCATIONS[actualLoc] && LOCATIONS[actualLoc].name) || actualLoc;
291	    StateManager.addMessage("🚶 你前往了 " + locName + "。", "info");
292	    consumeAP(travelAp);
293	  }
294	
295	  // 重新拿状态（consumeAP 可能导致状态重置）
296	  state = StateManager.getState();
297	  if (state.flags.gameOver) return;
298	
299	  // 执行 amenity
300	  applyAmenity(state, a);
301	  consumeAP(useAp);
302	}
303	
304	/**
305	 * 应用 amenity 效果：扣钱 + primary 主效果（按 tier 上限）+ bonusPool 真随机附加 + 标签习惯计数。
306	 */
307	function applyAmenity(state, a) {
308	  // === 食材消耗（在家做饭专用）===
309	  if (a.requiresIngredients) {
310	    var ingredientResult = consumeCookingIngredients(state, a);
311	    if (!ingredientResult.success) {
312	      StateManager.addMessage("🍳 " + ingredientResult.message, "warning");
313	      return;
314	    }
315	    // 食材消耗成功，记录烹饪经验
316	    if (typeof addCookingExp === "function") {
317	      addCookingExp(state, 15);
318	    }
319	  }
320	
321	  // 扣钱
322	  if (a.cost > 0) {
323	    state.resources.cash -= a.cost;
324	    if (typeof addDailyTransaction === "function") {
325	      addDailyTransaction(state, "expense", "amenity", a.cost, a.name);
326	    }
327	  }
328	
329	  // primary 主效果
330	  var msgParts = [];
331	  if (a.primary) {
332	    for (var key in a.primary) {
333	      if (!a.primary.hasOwnProperty(key)) continue;
334	      var amt = a.primary[key];
335	      if (
336	        key === "hunger" ||
337	        key === "fatigue" ||
338	        key === "hygiene" ||
339	        key === "happiness"
340	      ) {
341	        // fatigue 是反向：负值=减少疲劳=好；正值=增加疲劳=坏
342	        // 其他三项正值=补充
343	        var prev = state.needs[key];
344	        state.needs[key] = Math.max(0, Math.min(100, prev + amt));
345	        var delta = state.needs[key] - prev;
346	        msgParts.push(_needLabel(key) + (delta >= 0 ? "+" : "") + delta);
347	      } else if (
348	        key === "physique" ||
349	        key === "intelligence" ||
350	        key === "agility" ||
351	        key === "mental" ||
352	        key === "fame"
353	      ) {
354	        state.player[key] = Math.min(100, (state.player[key] || 0) + amt);
355	        msgParts.push(_attrLabel(key) + "+" + amt);
356	      } else if (key === "health") {
357	        state.status.health = Math.max(
358	          0,
359	          Math.min(100, state.status.health + amt),
360	        );
361	        msgParts.push("健康+" + amt);
362	      }
363	    }
364	  }
365	
366	  // 累计使用次数（用于规律性 buff，可选放大 chance）
367	  state.flags._amenityHabitCount = state.flags._amenityHabitCount || {};
368	  var prevUsed = state.flags._amenityHabitCount[a.id] || 0;
369	  state.flags._amenityHabitCount[a.id] = prevUsed + 1;
370	  // 规律性微加成：每使用 5 次，bonusPool 的 chance 整体 ×1.05（封顶 ×1.5）
371	  var habitMult = Math.min(1.5, 1.0 + Math.floor((prevUsed + 1) / 5) * 0.05);
372	
373	  // bonusPool 真随机附加效果
374	  if (a.bonusPool && a.bonusPool.length) {
375	    for (var i = 0; i < a.bonusPool.length; i++) {
376	      var b = a.bonusPool[i];
377	      var ch = (b.chance || 0) * habitMult;
378	      if (Math.random() < ch) {
379	        if (
380	          b.stat === "hunger" ||
381	          b.stat === "fatigue" ||
382	          b.stat === "hygiene" ||
383	          b.stat === "happiness"
384	        ) {
385	          state.needs[b.stat] = Math.max(
386	            0,
387	            Math.min(100, state.needs[b.stat] + b.amt),
388	          );
389	        } else if (b.stat === "fame") {
390	          state.player.fame = Math.min(100, (state.player.fame || 0) + b.amt);
391	        } else {
392	          state.player[b.stat] = Math.min(
393	            100,
394	            (state.player[b.stat] || 0) + b.amt,
395	          );
396	        }
397	        msgParts.push(
398	          "✨ " +
399	            (b.stat === "fame" ? "名气" : _attrLabel(b.stat)) +
400	            "+" +
401	            b.amt,
402	        );
403	      }
404	    }
405	  }
406	
407	  // 标签 → 习惯追踪
408	  state.flags._habits = state.flags._habits || {};
409	  if (a.junkFood) {
410	    state.flags._habits.junkFoodMeals =
411	      (state.flags._habits.junkFoodMeals || 0) + 1;
412	  }
413	  if (a.nutritious) {
414	    state.flags._habits.junkFoodMeals = Math.max(
415	      0,
416	      (state.flags._habits.junkFoodMeals || 0) - 2,
417	    );
418	  }
419	  if (a.lateNight) {
420	    state.flags._habits.lateNightActions =
421	      (state.flags._habits.lateNightActions || 0) + 1;
422	  }
423	
424	  // 清除该维度的延期标记（已经处理过了）
425	  if (state.flags._deferred) {
426	    if (a.type === "food") delete state.flags._deferred.hunger;
427	    if (a.type === "rest") delete state.flags._deferred.fatigue;
428	    if (a.type === "bath") delete state.flags._deferred.hygiene;
429	    if (a.type === "fun") delete state.flags._deferred.happiness;
430	  }
431	
432	  StateManager.addMessage(
433	    a.icon + " " + a.name + "：" + msgParts.join("，") + "。",
434	    "success",
435	  );
436	}
437	
438	function _needLabel(k) {
439	  return (
440	    { hunger: "饥饱", fatigue: "疲劳", hygiene: "卫生", happiness: "心情" }[
441	      k
442	    ] || k
443	  );
444	}
445	
446	function _attrLabel(k) {
447	  return (
448	    {
449	      physique: "体质",
450	      intelligence: "智力",
451	      agility: "敏捷",
452	      mental: "心智",
453	      fame: "名气",
454	      health: "健康",
455	    }[k] || k
456	  );
457	}
458	
459	// ====== 延期惩罚（endDay 调用）=====
460	// 阶梯式惩罚：延期次数越多，惩罚越重
461	// 第1次延期：轻度警告 + 小额健康/心情损失
462	// 第2次延期：中度惩罚 + 概率患病
463	// 第3次延期：重度惩罚 + 强制昏倒/送医
464	// 第4次+延期：极端后果（健康暴跌/强制住院/解雇风险）
465	
466	function applyDeferredCriticalPunishments(state) {
467	  if (!state.flags._deferred) return null;
468	
469	  var skipDay = false;
470	  var keys = Object.keys(state.flags._deferred);
471	  for (var i = 0; i < keys.length; i++) {
472	    var need = keys[i];
473	    var deferInfo = state.flags._deferred[need];
474	
475	    // 兼容旧格式：{ hunger: day } → 转为新格式
476	    if (typeof deferInfo === "number") {
477	      deferInfo = { count: 1, lastDay: deferInfo };
478	      state.flags._deferred[need] = deferInfo;
479	    }
480	
481	    // 检查是否是连续延期（同一天内不重复罚）
482	    if (deferInfo.lastDay === state.player.day) continue;
483	
484	    if (!isCriticalNeed(state, need)) continue; // 已经回血了不用罚
485	
486	    // 递增延期次数
487	    deferInfo.count = (deferInfo.count || 0) + 1;
488	    deferInfo.lastDay = state.player.day;
489	
490	    var result = _punishByNeed阶梯式(state, need, deferInfo.count);
491	    if (result === "skip_day") skipDay = true;
492	  }
493	
494	  // 清空当日延期标记（无论是否处罚）
495	  state.flags._deferred = {};
496	
497	  return skipDay ? "skip_day" : null;
498	}
499	
500	function _punishByNeed阶梯式(state, need, deferCount) {
501	  // deferCount: 第几次延期（1=轻度, 2=中度, 3=重度, 4+=极端）
502	  var skipDay = false;
503	
504	  if (need === "hunger") {
505	    if (deferCount === 1) {
506	      // 第1次延期：轻度 — 健康-3，饥饱降至15
507	      state.status.health = Math.max(0, state.status.health - 3);
508	      state.needs.hunger = Math.max(0, state.needs.hunger - 5);
509	      StateManager.addMessage(
510	        "😣 强忍饥饿撑过了一天，健康-3，肚子更难受了。",
511	        "warning",
512	      );
513	    } else if (deferCount === 2) {
514	      // 第2次延期：中度 — 健康-8，饥饱-10，概率得肠胃炎
515	      state.status.health = Math.max(0, state.status.health - 8);
516	      state.needs.hunger = Math.max(0, state.needs.hunger - 10);
517	      if (Math.random() < 0.4) {
518	        _contractIllness(state, "stomach_inflammation");
519	      }
520	      StateManager.addMessage(
521	        "🤢 连续两天挨饿，健康-8，肠胃开始抗议...",
522	        "danger",
523	      );
524	    } else if (deferCount === 3) {
525	      // 第3次延期：重度 — 饿晕，健康-15，饥饱重置为8
526	      state.status.health = Math.max(0, state.status.health - 15);
527	      state.needs.hunger = 8;
528	      StateManager.addMessage(
529	        "💀 你饿晕在街头！醒来已是深夜，健康-15。",
530	        "danger",
531	      );
532	      skipDay = true;
533	    } else {
