792	/**
793	 * 消耗烹饪食材：从库存中扣除所需食材
794	 * @param {Object} state - 游戏状态
795	 * @param {Object} amenity - amenity 定义（含 requiresIngredients: true）
796	 * @returns {{success: boolean, message: string, consumed: Array}}
797	 */
798	function consumeCookingIngredients(state, amenity) {
799	  // 兼容两种库存格式：
800	  //   1) state.inventory = [{ itemId, quantity }] (cooking.js 格式)
801	  //   2) state.inventory = { items: [{ id, qty }], capacity } (实际 state 格式)
802	  var inv = state.inventory;
803	  var isOldFormat = Array.isArray(inv);
804	  if (!inv)
805	    inv = state.inventory = isOldFormat ? [] : { items: [], capacity: 20 };
806	  if (!isOldFormat && !inv.items) inv.items = [];
807	
808	  // 如果食谱指定了要 cookRecipe，就走全食谱流程（显示食谱选择）
809	  if (amenity.useRecipeSelection) {
810	    return { success: true, message: "打开食谱选择", useRecipeSelection: true };
811	  }
812	
813	  // 默认食材消耗（在家做饭的基础食材组合）
814	  var defaultIngredients = [
815	    { itemId: "rice", amount: 1 },
816	    { itemId: "egg", amount: 1 },
817	    { itemId: "salt", amount: 1 },
818	    { itemId: "cooking_oil", amount: 1 },
819	  ];
820	
821	  // 如果有自定义食材需求，使用自定义
822	  var ingredients = amenity.cookingIngredients || defaultIngredients;
823	
824	  // 检查食材
825	  var missing = [];
826	  for (var i = 0; i < ingredients.length; i++) {
827	    var ing = ingredients[i];
828	    var found = null;
829	    if (isOldFormat) {
830	      for (var j = 0; j < inv.length; j++) {
831	        if (inv[j].itemId === ing.itemId) {
832	          found = inv[j];
833	          break;
834	        }
835	      }
836	    } else {
837	      for (var j = 0; j < inv.items.length; j++) {
838	        if (inv.items[j].id === ing.itemId) {
839	          found = inv.items[j];
840	          break;
841	        }
842	      }
843	    }
844	    if (!found || found.quantity < ing.amount) {
845	      var itemDef =
846	        typeof getItemById === "function" && getItemById(ing.itemId);
847	      missing.push({
848	        itemId: ing.itemId,
849	        itemName: itemDef ? itemDef.name : ing.itemId,
850	        icon: itemDef ? itemDef.icon : "📦",
851	        needed: ing.amount,
852	        have: found ? found.quantity : 0,
853	      });
854	    }
855	  }
856	
857	  if (missing.length > 0) {
858	    var missingText = missing
859	      .map(function (m) {
860	        return m.icon + m.itemName + "(需" + m.needed + ", 有" + m.have + ")";
861	      })
862	      .join(", ");
863	    return {
864	      success: false,
865	      message: "食材不足：" + missingText,
866	      missing: missing,
867	    };
868	  }
869	
870	  // 消耗食材
871	  var consumed = [];
872	  for (var i = 0; i < ingredients.length; i++) {
873	    var ing = ingredients[i];
874	    if (isOldFormat) {
875	      for (var j = 0; j < inv.length; j++) {
876	        if (inv[j].itemId === ing.itemId) {
877	          inv[j].quantity -= ing.amount;
878	          consumed.push({ itemId: ing.itemId, amount: ing.amount });
879	          if (inv[j].quantity <= 0) {
880	            inv.splice(j, 1);
881	            j--;
882	          }
883	          break;
884	        }
885	      }
886	    } else {
887	      for (var j = 0; j < inv.items.length; j++) {
888	        if (inv.items[j].id === ing.itemId) {
889	          inv.items[j].qty -= ing.amount;
890	          consumed.push({ itemId: ing.itemId, amount: ing.amount });
891	          if (inv.items[j].qty <= 0) {
892	            inv.items.splice(j, 1);
893	            j--;
894	          }
895	          break;
896	        }
897	      }
898	    }
899	  }
900	
901	  return { success: true, message: "食材消耗成功", consumed: consumed };
902	}
