909	function _canCookRecipeByState(state, recipe) {
910	  var inv = state.inventory;
911	  if (!inv) return false;
912	  var items = inv.items || (Array.isArray(inv) ? inv : []);
913	  for (var i = 0; i < recipe.ingredients.length; i++) {
914	    var ing = recipe.ingredients[i];
915	    var found = null;
916	    for (var j = 0; j < items.length; j++) {
917	      // 兼容两种 key 名：id / itemId
918	      var fid = items[j].id || items[j].itemId;
919	      if (fid === ing.itemId) {
920	        found = items[j];
921	        break;
922	      }
923	    }
924	    var qty = found ? found.qty || found.quantity || 0 : 0;
925	    if (qty < ing.amount) return false;
926	  }
927	  return true;
928	}
